def build_pan_india_file():
    target_file = os.path.join(os.path.dirname(__file__), "all_india_zones.json")
    with open(target_file, "w", encoding="utf-8") as f:
        json.dump(PAN_INDIA_DATA, f, indent=2, ensure_ascii=False)
    print(f"Generated {len(PAN_INDIA_DATA)} Pan-India locations in {target_file}")

if __name__ == "__main__":
    build_pan_india_file()
